  const proc = spawn(
    "chromium",
    ["--headless=new", "--disable-gpu", "--no-sandbox", `--remote-debugging-port=${port}`, `--user-data-dir=${join(outDir, ".profile")}`, "about:blank"],
    { stdio: "ignore" },
