              {data.account ? ` · ${data.account}` : ""}
              {!finished && repos.length > 0 ? " · updating every 5 s" : ""}
            </p>

            {data.state === "rejected" && (
              <p className="mt-4" role="status">
                <span aria-hidden className="font-mono">✗ </span>
